#include <cstddef>

extern "C" void run(const void* input1, const void* input2, void* output,
                    int n, int parameter, int threads)
{
    (void)parameter;
    (void)threads;
    if (n <= 0) return;

    const float* A = static_cast<const float*>(input1);
    const float* B = static_cast<const float*>(input2);
    float* C = static_cast<float*>(output);
    constexpr int ROWS = 12;
    constexpr int COLS = 16;

    int r = 0;
    for (; r <= n - ROWS; r += ROWS) {
        int c = 0;
        for (; c <= n - COLS; c += COLS) {
            float acc[ROWS][COLS] = {};
            int k = 0;
            for (; k <= n - 4; k += 4) {
                for (int q = 0; q < 4; ++q) {
                    const int kk = k + q;
                    const float* brow = B + static_cast<std::size_t>(kk) * n + c;
                    for (int i = 0; i < ROWS; ++i) {
                        const float a = A[static_cast<std::size_t>(r + i) * n + kk];
                        #pragma omp simd
                        for (int j = 0; j < COLS; ++j)
                            acc[i][j] += a * brow[j];
                    }
                }
            }
            for (; k < n; ++k) {
                const float* brow = B + static_cast<std::size_t>(k) * n + c;
                for (int i = 0; i < ROWS; ++i) {
                    const float a = A[static_cast<std::size_t>(r + i) * n + k];
                    #pragma omp simd
                    for (int j = 0; j < COLS; ++j)
                        acc[i][j] += a * brow[j];
                }
            }
            for (int i = 0; i < ROWS; ++i) {
                float* crow = C + static_cast<std::size_t>(r + i) * n + c;
                for (int j = 0; j < COLS; ++j)
                    crow[j] = acc[i][j];
            }
        }
        for (; c < n; ++c) {
            for (int i = 0; i < ROWS; ++i) {
                float sum = 0.0f;
                for (int k = 0; k < n; ++k)
                    sum += A[static_cast<std::size_t>(r + i) * n + k] *
                           B[static_cast<std::size_t>(k) * n + c];
                C[static_cast<std::size_t>(r + i) * n + c] = sum;
            }
        }
    }
    for (; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            float sum = 0.0f;
            for (int k = 0; k < n; ++k)
                sum += A[static_cast<std::size_t>(r) * n + k] *
                       B[static_cast<std::size_t>(k) * n + c];
            C[static_cast<std::size_t>(r) * n + c] = sum;
        }
    }
}
